use crate::dataset::Subject;
use crate::numerics::{solve, Matrix};

pub struct EventRisk {
    pub time: i64,
    pub events: usize,
    pub s0: f64,
    pub s1: Vec<f64>,
}

pub struct Evaluation {
    pub likelihood: f64,
    pub score: Vec<f64>,
    pub information: Matrix,
    pub theta: Vec<f64>,
    pub event_risks: Vec<EventRisk>,
}

pub fn evaluate(subjects: &[Subject], x: &[Vec<i64>], beta: &[f64]) -> Evaluation {
    let p = beta.len();
    let theta: Vec<_> = x.iter().map(|row| row.iter().zip(beta).fold(0.0, |total, (&x, &b)| total + b * x as f64)).collect();
    let risks: Vec<_> = theta.iter().map(|&theta| theta.exp()).collect();
    let mut order: Vec<_> = (0..subjects.len()).collect();
    order.sort_by_key(|&i| (-subjects[i].time, subjects[i].id));
    let mut result = Evaluation { likelihood: 0.0, score: vec![0.0; p], information: vec![vec![0.0; p]; p], theta, event_risks: Vec::new() };
    let mut s0 = 0.0;
    let mut s1 = vec![0.0; p];
    let mut s2 = vec![vec![0.0; p]; p];
    let mut i = 0;
    while i < order.len() {
        let time = subjects[order[i]].time;
        let mut events = Vec::new();
        while i < order.len() && subjects[order[i]].time == time {
            let index = order[i];
            let risk = risks[index];
            s0 += risk;
            for c in 0..p {
                s1[c] += risk * x[index][c] as f64;
                for d in 0..p { s2[c][d] += risk * x[index][c] as f64 * x[index][d] as f64; }
            }
            if subjects[index].event { events.push(index); }
            i += 1;
        }
        if events.is_empty() { continue; }
        let e = events.len() as f64;
        result.likelihood += events.iter().fold(0.0, |sum, &i| sum + result.theta[i]) - e * s0.ln();
        for c in 0..p {
            result.score[c] += events.iter().map(|&i| x[i][c]).sum::<i64>() as f64 - e * s1[c] / s0;
            for d in 0..p { result.information[c][d] += e * (s2[c][d] / s0 - (s1[c] / s0) * (s1[d] / s0)); }
        }
        result.event_risks.push(EventRisk { time, events: events.len(), s0, s1: s1.clone() });
    }
    result
}

pub struct Fit {
    pub beta: Vec<f64>,
    pub history: Vec<(f64, Vec<f64>)>,
    pub null: Evaluation,
    pub final_evaluation: Evaluation,
}

pub fn fit(subjects: &[Subject], x: &[Vec<i64>]) -> Fit {
    let mut beta = vec![0.0; x[0].len()];
    let null = evaluate(subjects, x, &beta);
    let mut history = Vec::new();
    for _ in 0..25 {
        let evaluation = evaluate(subjects, x, &beta);
        let delta = solve(&evaluation.information, &evaluation.score);
        for (beta, delta) in beta.iter_mut().zip(delta) { *beta += delta; }
        history.push((evaluation.likelihood, beta.clone()));
    }
    let final_evaluation = evaluate(subjects, x, &beta);
    Fit { beta, history, null, final_evaluation }
}

use std::collections::BTreeMap;
use std::fs;

#[derive(Clone)]
pub struct Subject {
    pub id: usize,
    pub group: usize,
    pub time: i64,
    pub event: bool,
    pub age: i64,
    pub sex: u8,
    pub stage: i64,
}

pub struct Input {
    pub subjects: Vec<Subject>,
    pub groups: Vec<String>,
    pub params: BTreeMap<String, Vec<String>>,
}

impl Input {
    pub fn number(&self, name: &str) -> i64 { self.params[name][0].parse().unwrap() }
    pub fn numbers(&self, name: &str) -> Vec<i64> { self.params[name].iter().map(|v| v.parse().unwrap()).collect() }
}

pub fn read() -> Input {
    let params: BTreeMap<String, Vec<String>> = fs::read_to_string("input/params.txt").unwrap().lines().map(|line| {
        let mut parts = line.split(' ');
        (parts.next().unwrap().into(), parts.map(String::from).collect())
    }).collect();
    let groups = params["GROUPS"].clone();
    let mut subjects: Vec<_> = fs::read_to_string("input/subjects.csv").unwrap().lines().skip(1).map(|line| {
        let p: Vec<_> = line.split(',').collect();
        Subject { id: p[0].parse().unwrap(), group: groups.iter().position(|g| g == p[1]).unwrap(), time: p[2].parse().unwrap(), event: p[3] == "1", age: p[4].parse().unwrap(), sex: p[5].as_bytes()[0], stage: p[6].parse().unwrap() }
    }).collect();
    subjects.sort_by_key(|subject| subject.id);
    Input { subjects, groups, params }
}

use crate::dataset::Subject;
use crate::Z;
use std::collections::BTreeSet;

#[derive(Clone)]
pub struct KmRow {
    pub time: i64,
    pub risk: usize,
    pub events: usize,
    pub censored: usize,
    pub survival: f64,
    pub error: Option<f64>,
    pub lower: Option<f64>,
    pub upper: Option<f64>,
    pub hazard: f64,
    pub hazard_error: f64,
}

pub fn kaplan_meier(subjects: &[Subject], reverse: bool) -> Vec<KmRow> {
    let times: Vec<_> = subjects.iter().filter(|s| s.event != reverse).map(|s| s.time).collect::<BTreeSet<_>>().into_iter().collect();
    let (mut survival, mut greenwood, mut hazard, mut hazard_variance) = (1.0, Some(0.0), 0.0, 0.0);
    let mut rows = Vec::new();
    for (i, &time) in times.iter().enumerate() {
        let risk = subjects.iter().filter(|s| s.time >= time).count();
        let events = subjects.iter().filter(|s| s.time == time && s.event != reverse).count();
        let censored = subjects.iter().filter(|s| s.event == reverse && s.time >= time && times.get(i + 1).is_none_or(|&next| s.time < next)).count();
        survival *= (risk - events) as f64 / risk as f64;
        greenwood = if risk == events { None } else { greenwood.map(|g| g + events as f64 / (risk * (risk - events)) as f64) };
        let (error, lower, upper) = if let Some(g) = greenwood {
            let logarithm = survival.ln();
            let omega = Z * g.sqrt() / (-logarithm);
            (Some(survival * g.sqrt()), Some((logarithm * omega.exp()).exp()), Some((logarithm * (-omega).exp()).exp()))
        } else { (None, None, None) };
        hazard += events as f64 / risk as f64;
        hazard_variance += events as f64 / (risk * risk) as f64;
        rows.push(KmRow { time, risk, events, censored, survival, error, lower, upper, hazard, hazard_error: hazard_variance.sqrt() });
    }
    rows
}

pub fn at(rows: &[KmRow], time: i64) -> KmRow {
    rows.iter().rev().find(|row| row.time <= time).cloned().unwrap_or(KmRow { time: 0, risk: 0, events: 0, censored: 0, survival: 1.0, error: Some(0.0), lower: None, upper: None, hazard: 0.0, hazard_error: 0.0 })
}

pub struct LifeRow {
    pub start: i64,
    pub end: i64,
    pub risk: usize,
    pub events: usize,
    pub withdrawn: usize,
    pub exposed: f64,
    pub q: f64,
    pub survival: f64,
    pub error: f64,
    pub hazard: f64,
}

pub fn life_table(subjects: &[Subject], width: i64, count: i64) -> Vec<LifeRow> {
    let mut rows = Vec::new();
    let (mut survival, mut variance) = (1.0, 0.0);
    for i in 0..count {
        let start = i * width;
        let end = (i + 1) * width;
        let risk = subjects.iter().filter(|s| s.time >= start).count();
        let events = subjects.iter().filter(|s| start <= s.time && s.time < end && s.event).count();
        let withdrawn = subjects.iter().filter(|s| start <= s.time && s.time < end && !s.event).count();
        let f = (2 * risk - withdrawn) as i64;
        survival *= (f - 2 * events as i64) as f64 / f as f64;
        variance += (4 * events) as f64 / (f * (f - 2 * events as i64)) as f64;
        rows.push(LifeRow { start, end, risk, events, withdrawn, exposed: f as f64 / 2.0, q: (2 * events) as f64 / f as f64, survival, error: survival * variance.sqrt(), hazard: (2000 * events) as f64 / (width * (f - events as i64)) as f64 });
    }
    rows
}

use crate::dataset::Subject;
use crate::numerics::{p_value, solve, Matrix};
use std::collections::BTreeSet;

pub struct Test {
    pub groups: Vec<usize>,
    pub events: Vec<usize>,
    pub observed: Vec<f64>,
    pub expected: Vec<f64>,
    pub covariance: Matrix,
    pub statistic: f64,
    pub p: f64,
}

impl Test {
    pub fn empty(groups: &[usize]) -> Self {
        let k = groups.len();
        Self { groups: groups.to_vec(), events: vec![0; k], observed: vec![0.0; k], expected: vec![0.0; k], covariance: vec![vec![0.0; k]; k], statistic: 0.0, p: 1.0 }
    }
    pub fn add(&mut self, other: &Self) {
        for i in 0..self.groups.len() {
            self.events[i] += other.events[i];
            self.observed[i] += other.observed[i];
            self.expected[i] += other.expected[i];
            for j in 0..self.groups.len() { self.covariance[i][j] += other.covariance[i][j]; }
        }
    }
    pub fn finish(&mut self) {
        let n = self.groups.len() - 1;
        let matrix = self.covariance[..n].iter().map(|row| row[..n].to_vec()).collect();
        let u: Vec<_> = (0..n).map(|i| self.observed[i] - self.expected[i]).collect();
        let x = solve(&matrix, &u);
        self.statistic = u.iter().zip(x).fold(0.0, |total, (&u, x)| total + u * x);
        self.p = p_value(self.statistic, n);
    }
}

pub fn weighted(subjects: &[Subject], groups: &[usize], kind: &str, total_subjects: usize) -> Test {
    let mut result = Test::empty(groups);
    let times: BTreeSet<_> = subjects.iter().filter(|s| s.event).map(|s| s.time).collect();
    for time in times {
        let risk: Vec<_> = groups.iter().map(|&g| subjects.iter().filter(|s| s.group == g && s.time >= time).count() as i64).collect();
        let events: Vec<_> = groups.iter().map(|&g| subjects.iter().filter(|s| s.group == g && s.time == time && s.event).count() as i64).collect();
        let n = risk.iter().sum::<i64>();
        let d = events.iter().sum::<i64>();
        let weight = match kind { "gehan_wilcoxon" => n as f64 / total_subjects as f64, "tarone_ware" => (n as f64 / total_subjects as f64).sqrt(), _ => 1.0 };
        for h in 0..groups.len() {
            result.events[h] += events[h] as usize;
            result.observed[h] += weight * events[h] as f64;
            result.expected[h] += weight * ((d * risk[h]) as f64 / n as f64);
            if n >= 2 {
                let factor = (d * (n - d)) as f64 / ((n - 1) * n * n) as f64;
                for l in 0..groups.len() {
                    let m = if h == l { risk[h] * (n - risk[h]) } else { -(risk[h] * risk[l]) };
                    result.covariance[h][l] += weight * weight * factor * m as f64;
                }
            }
        }
    }
    result.finish();
    result
}

