    let tables: Vec<_> = collections.iter().map(|subjects| kaplan_meier(subjects, false)).collect();
    let life_params = input.numbers("LIFE_TABLE");
    let life: Vec<_> = collections.iter().map(|subjects| life_table(subjects, life_params[0], life_params[1])).collect();
    let mut km_lines = Vec::new();
    let mut summaries = Vec::new();
    let mut life_lines = vec!["group,interval,at_risk,events,withdrawn,exposed,q,survival,std_err,hazard".into()];
    for i in 0..collections.len() {
        let (block, summary) = collection_report(&names[i], &collections[i], &tables[i], &life[i], &input);
        append(&mut km_lines, block);
        summaries.push(summary);
        for row in &life[i] { life_lines.push(format!("{},{}-{},{},{},{},{:.1},{},{},{},{}", names[i], row.start, row.end, row.risk, row.events, row.withdrawn, row.exposed, real(row.q), real(row.survival), real(row.error), real(row.hazard))); }
    }
    let plot_params = input.numbers("PLOT");
    let mut plot = plot::render(&input.groups, &collections, &tables, plot_params[0] as usize, plot_params[1] as usize, plot_params[2]);
    let times: Vec<_> = (0..=plot_params[3]).map(|i| i * (plot_params[2] / plot_params[3])).collect();
    plot.push(format!("at_risk {}", times.iter().map(i64::to_string).collect::<Vec<_>>().join(" ")));
    for g in 0..input.groups.len() { plot.push(format!("{} {}", input.groups[g], times.iter().map(|&time| collections[g].iter().filter(|s| s.time >= time).count().to_string()).collect::<Vec<_>>().join(" "))); }
    fs::create_dir_all("output").unwrap();
    write("km_tables.txt", &km_lines);
    write("life_table.csv", &life_lines);
    write("tests.txt", &tests(&input, &collections, &names, &tables, &summaries));
    write("cox.txt", &cox_report(&input));
    write("km_plot.txt", &plot);
}

pub type Matrix = Vec<Vec<f64>>;
pub fn sum(values: impl IntoIterator<Item = f64>) -> f64 { values.into_iter().fold(0.0, |total, v| total + v) }

pub fn solve(matrix: &Matrix, right: &[f64]) -> Vec<f64> {
    let mut a = matrix.clone();
    let mut b = right.to_vec();
    let n = b.len();
    for k in 0..n {
        for i in k + 1..n {
            let factor = a[i][k] / a[k][k];
            for j in k..n {
                let correction = factor * a[k][j];
                a[i][j] -= correction;
            }
            let correction = factor * b[k];
            b[i] -= correction;
        }
    }
    let mut solution = vec![0.0; n];
    for i in (0..n).rev() {
        let mut value = b[i];
        for j in i + 1..n { value -= a[i][j] * solution[j]; }
        solution[i] = value / a[i][i];
    }
    solution
}

pub fn inverse(matrix: &Matrix) -> Matrix {
    let n = matrix.len();
    let mut result = vec![vec![0.0; n]; n];
    for column in 0..n {
        let mut unit = vec![0.0; n];
        unit[column] = 1.0;
        let solution = solve(matrix, &unit);
        for row in 0..n { result[row][column] = solution[row]; }
    }
    result
}

fn log_gamma(a: f64) -> f64 {
    let coefficients = [76.18009172947146, -86.50532032941677, 24.01409824083091, -1.231739572450155, 0.001208650973866179, -0.000005395239384953];
    let x0 = a + 5.5;
    let x1 = x0 - (a + 0.5) * x0.ln();
    let mut sigma = 1.000000000190015;
    let mut y = a;
    for coefficient in coefficients { y += 1.0; sigma += coefficient / y; }
    -x1 + (2.5066282746310005 * sigma / a).ln()
}

fn gamma_q(a: f64, x: f64) -> f64 {
    if x == 0.0 { return 1.0; }
    let prefactor = (-x + a * x.ln() - log_gamma(a)).exp();
    if x < a + 1.0 {
        let mut alpha = a;
        let mut term = 1.0 / a;
        let mut total = term;
        for _ in 0..1000 {
            alpha += 1.0;
            term *= x / alpha;
            total += term;
            if term.abs() < total.abs() * 1e-15 { break; }
        }
        1.0 - total * prefactor
    } else {
        let epsilon = 1e-300;
        let mut b = x + 1.0 - a;
        let mut c = 1.0 / epsilon;
        let mut d = 1.0 / b;
        let mut h = d;
        for i in 1..=1000 {
            let i = i as f64;
            let an = -i * (i - a);
            b += 2.0;
            d = an * d + b;
            if d.abs() < epsilon { d = epsilon; }
            c = b + an / c;
            if c.abs() < epsilon { c = epsilon; }
            d = 1.0 / d;
            let delta = d * c;
            h *= delta;
            if (delta - 1.0).abs() < 1e-15 { break; }
        }
        prefactor * h
    }
}

pub fn p_value(statistic: f64, degrees: usize) -> f64 { gamma_q(degrees as f64 / 2.0, statistic / 2.0) }

use crate::dataset::Subject;
use crate::estimators::{at, KmRow};

pub fn render(names: &[String], collections: &[Vec<Subject>], tables: &[Vec<KmRow>], width: usize, height: usize, time: i64) -> Vec<String> {
    let mut cells = vec![vec![b' '; width]; height];
    for (g, subjects) in collections.iter().take(names.len()).enumerate() {
        let maximum = subjects.iter().map(|s| s.time).max().unwrap();
        let mut previous = None;
        for column in 0..width {
            let t = column as i64 * (time / width as i64);
            if t > maximum { break; }
            let band = ((at(&tables[g], t).survival * height as f64).floor() as usize).min(height - 1);
            let mut occupied = vec![band];
            if let Some(previous) = previous { if previous > band + 1 { occupied.extend(band + 1..previous); } }
            for band in occupied {
                let cell = &mut cells[height - 1 - band][column];
                *cell = if *cell == b' ' { b'A' + g as u8 } else { b'*' };
            }
            previous = Some(band);
        }
    }
    let mut lines = vec![format!("km_plot width {width} height {height} time {time}"), format!("legend {}", names.iter().enumerate().map(|(i, name)| format!("{} {}", (b'A' + i as u8) as char, name)).collect::<Vec<_>>().join(" "))];
    let border = format!("   +{}+", "-".repeat(width));
    lines.push(border.clone());
    for (row, cells) in cells.iter().enumerate() { lines.push(format!("{:3}|{}|", 100 * (height - 1 - row) / height, String::from_utf8(cells.clone()).unwrap())); }
    lines.push(border);
    lines.push(format!("time 0 to {time} days, {} days per column", time / width as i64));
    lines
}
